"""matplotlib.sankey — Sankey diagram.

The shim tracks the flow inputs that ``add()`` records so introspection
matches upstream — ``Sankey.finish()`` returns a list of
:class:`SankeyDiagram` instances with the same attributes (``patch``,
``flows``, ``angles``, ``texts``, ``tips``, ``text``).
"""

import numpy as _np
from matplotlib.artist import Artist


# Direction codes used to lay out flow paths. Integers so they
# combine cleanly when summed in the path tracer.
UP    =  1
RIGHT =  0
DOWN  = -1


class SankeyDiagram:
    """One diagram instance produced by :meth:`Sankey.add`. Mirrors
    upstream's namedtuple-like object with five fields."""

    def __init__(self, patch=None, flows=None, angles=None, tips=None,
                  text=None, texts=None):
        self.patch = patch
        self.flows = _np.asarray(flows) if flows is not None else _np.array([])
        self.angles = list(angles) if angles else []
        self.tips = _np.asarray(tips) if tips is not None else _np.empty((0, 2))
        self.text = text
        self.texts = list(texts) if texts else []


class Sankey:
    """Build a Sankey (flow) diagram. ``add()`` registers one cluster
    of flows; ``finish()`` returns the list of :class:`SankeyDiagram`
    instances built up so far."""

    def __init__(self, ax=None, scale=1.0, unit='', format='%G', gap=0.25,
                 radius=0.1, shoulder=0.03, offset=0.15, head_angle=100,
                 margin=0.4, tolerance=1e-6, **kwargs):
        self.ax = ax
        self.scale = float(scale)
        self.unit = unit
        self.format = format
        self.gap = float(gap)
        self.radius = float(radius)
        self.shoulder = float(shoulder)
        self.offset = float(offset)
        self.head_angle = float(head_angle)
        self.margin = float(margin)
        self.tolerance = float(tolerance)
        self.diagrams = []

    def add(self, patchlabel='', flows=None, orientations=None, labels='',
            trunklength=1.0, pathlengths=0.25, prior=None, connect=None,
            rotation=0, **kwargs):
        """Register a flow cluster. Returns ``self`` for chaining,
        matching upstream's fluent API."""
        flows = _np.atleast_1d(_np.asarray(flows or [], dtype=float))
        n = len(flows)
        # Default orientations / labels / lengths to match upstream.
        if orientations is None:
            orientations = [0] * n
        elif _np.isscalar(orientations):
            orientations = [int(orientations)] * n
        if isinstance(labels, str):
            labels = [labels] * n
        if _np.isscalar(pathlengths):
            pathlengths = [float(pathlengths)] * n
        # Tip positions: equally spaced around a unit circle for the
        # shim (real upstream computes exact arc positions, but plotly
        # renders Sankey itself via go.Sankey so we only need plausible
        # data here).
        angles_rad = _np.linspace(0, 2 * _np.pi, max(n, 1), endpoint=False)
        tips = _np.column_stack([_np.cos(angles_rad) * trunklength,
                                  _np.sin(angles_rad) * trunklength])
        diagram = SankeyDiagram(
            patch=None,                   # plotly renders the patch itself
            flows=flows,
            angles=list(orientations),
            tips=tips,
            text=patchlabel,
            texts=list(labels))
        self.diagrams.append(diagram)
        return self

    def finish(self):
        """Return the list of built diagrams. Each is a
        :class:`SankeyDiagram` (mirrors upstream's namedtuple)."""
        return list(self.diagrams)
